-- Mensaje 132 (3-nov-2026): el «no» que invita a seguir (decisión de Emilio).
-- Cerebro v17 → v18 (un párrafo después de «Dos no seguidos») y la prueba de tres reglas.
-- Protegido: solo cambia si el Cerebro vigente es el v17 con el texto esperado y cada regla tiene su texto de hoy.
-- Correrlo dos veces no cambia nada.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$**El «no» que invita** `CAMPO`: si el cliente te dice que no pero en la misma respuesta te invita a seguir —*"de verdad traigo prisa, ¿qué necesita saber exactamente?"*—, sí es un «no», pero la puerta sigue abierta. Contestarle no es insistir: hasta puede ser una señal de interés. Ve directo a lo que pregunta.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene el cambio del 132.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF v <> 17 THEN RAISE EXCEPTION 'se esperaba el Cerebro v17 y está el v%', v; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$Insistir más ya no es seguridad: es terquedad. Al buscar el hueco es igual: si dos intentos seguidos se topan con un «no», dejas de buscar y lo retomas en otra visita. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre es igual (ver La Regla de los No).$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado de «Dos no seguidos»'; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title,
         replace(body, $v$Insistir más ya no es seguridad: es terquedad. Al buscar el hueco es igual: si dos intentos seguidos se topan con un «no», dejas de buscar y lo retomas en otra visita. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre es igual (ver La Regla de los No).$v$, $v$Insistir más ya no es seguridad: es terquedad. Al buscar el hueco es igual: si dos intentos seguidos se topan con un «no», dejas de buscar y lo retomas en otra visita. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre es igual (ver La Regla de los No).

**El «no» que invita** `CAMPO`: si el cliente te dice que no pero en la misma respuesta te invita a seguir —*"de verdad traigo prisa, ¿qué necesita saber exactamente?"*—, sí es un «no», pero la puerta sigue abierta. Contestarle no es insistir: hasta puede ser una señal de interés. Ve directo a lo que pregunta.$v$),
         true, created_by
  FROM public.doctrina WHERE version = v AND is_active;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Si dice que no pero en la misma respuesta invita al vendedor a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, sí es un «no», pero la puerta sigue abierta: contestar su invitación no es insistir. Seguidos: entre uno y otro la conversación no avanzó.$v$, updated_at = now()
WHERE id = 'blocks.insistir_tras_dos_no' AND resumen = $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$;
UPDATE public.reglas SET resumen = $v$En cualquier momento de la visita, también en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar; en el cierre, despedirse bien y dejar la puerta abierta). «Lo voy a pensar» es una objeción, no un «no». LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Si dice que no pero en la misma respuesta invita al vendedor a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, sí es un «no», pero la puerta sigue abierta: contestar su invitación no es insistir. Seguidos: entre uno y otro la conversación no avanzó.$v$, updated_at = now()
WHERE id = 'flow.dos_no_seguidos' AND resumen = $v$En cualquier momento de la visita, también en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar; en el cierre, despedirse bien y dejar la puerta abierta). «Lo voy a pensar» es una objeción, no un «no». LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$;
UPDATE public.reglas SET resumen = $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. LA PRUEBA: después del segundo «no» seguido en la puerta, ¿el vendedor queda de regresar —mejor con una alternativa concreta, como jueves o viernes— o se despide con amabilidad, sin seguir con su tema? Cualquiera de las dos cumple; si sigue con su tema, no cumple. Si el segundo «no» trae una invitación a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, la puerta sigue abierta: contestarle no es insistir, y el criterio es no_aplica.$v$, updated_at = now()
WHERE id = 'blocks.dos_no_seguidos' AND resumen = $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. LA PRUEBA: después del segundo «no» seguido en la puerta, ¿el vendedor queda de regresar —mejor con una alternativa concreta, como jueves o viernes— o se despide con amabilidad, sin seguir con su tema? Cualquiera de las dos cumple; si sigue con su tema, no cumple.$v$;

DO $chk$ BEGIN
  IF (SELECT max(version) FROM public.doctrina WHERE is_active) <> 18 THEN RAISE EXCEPTION 'el Cerebro no quedó en v18'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$**El «no» que invita** `CAMPO`: si el cliente te dice que no pero en la misma respuesta te invita a seguir —*"de verdad traigo prisa, ¿qué necesita saber exactamente?"*—, sí es un «no», pero la puerta sigue abierta. Contestarle no es insistir: hasta puede ser una señal de interés. Ve directo a lo que pregunta.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el párrafo nuevo no quedó en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.insistir_tras_dos_no') IS DISTINCT FROM $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Si dice que no pero en la misma respuesta invita al vendedor a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, sí es un «no», pero la puerta sigue abierta: contestar su invitación no es insistir. Seguidos: entre uno y otro la conversación no avanzó.$v$ THEN RAISE EXCEPTION 'la regla blocks.insistir_tras_dos_no no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'flow.dos_no_seguidos') IS DISTINCT FROM $v$En cualquier momento de la visita, también en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar; en el cierre, despedirse bien y dejar la puerta abierta). «Lo voy a pensar» es una objeción, no un «no». LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Si dice que no pero en la misma respuesta invita al vendedor a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, sí es un «no», pero la puerta sigue abierta: contestar su invitación no es insistir. Seguidos: entre uno y otro la conversación no avanzó.$v$ THEN RAISE EXCEPTION 'la regla flow.dos_no_seguidos no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.dos_no_seguidos') IS DISTINCT FROM $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. LA PRUEBA: después del segundo «no» seguido en la puerta, ¿el vendedor queda de regresar —mejor con una alternativa concreta, como jueves o viernes— o se despide con amabilidad, sin seguir con su tema? Cualquiera de las dos cumple; si sigue con su tema, no cumple. Si el segundo «no» trae una invitación a seguir —«de verdad traigo prisa, ¿qué necesita saber exactamente?», «dígame rápido»—, la puerta sigue abierta: contestarle no es insistir, y el criterio es no_aplica.$v$ THEN RAISE EXCEPTION 'la regla blocks.dos_no_seguidos no quedó'; END IF;
END $chk$;
